let r = null;
try { r = $(QUERY_NODE).first().json; } catch (e) { r = null; }
if (!r || typeof r !== 'object') return failed('query node produced no result');
if (r.error) return failed('query request failed (no answer from Grafana)');
if (r.statusCode !== 200) return failed('Grafana answered HTTP ' + str(r.statusCode));
const body = r.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) return failed('Grafana answer is not JSON');
let size = 0;
try { size = JSON.stringify(body).length; } catch (e) { return failed('Grafana answer cannot be read'); }
if (size > MAX_BYTES) return failed('Grafana answer too large (' + size + ' bytes)');
const results = body.results;
if (!results || typeof results !== 'object') return failed('Grafana answer has no results');
// -> array of {labels, points:[{t, v}]}, or a string error
function readRef(ref) {
  const res = results[ref];
  if (!res || typeof res !== 'object') return 'query ' + ref + ' missing from the answer';
  if (res.error || (res.status !== undefined && res.status !== 200)) return 'query ' + ref + ' reported an error';
  if (res.frames === undefined || res.frames === null) return [];
  if (!Array.isArray(res.frames)) return 'query ' + ref + ' answer malformed';
  if (res.frames.length > MAX_SERIES) return 'query ' + ref + ' returned too many series';
  const out = [];
  for (const fr of res.frames) {
    const fields = fr && fr.schema && fr.schema.fields;
    const vals = fr && fr.data && fr.data.values;
    if (!Array.isArray(fields) || !Array.isArray(vals) || vals.length !== fields.length) return 'query ' + ref + ' answer malformed';
    const ti = fields.findIndex((f) => f && f.type === 'time');
    const vi = fields.findIndex((f) => f && f.type !== 'time');
    if (ti < 0 || vi < 0 || !Array.isArray(vals[ti]) || !Array.isArray(vals[vi])) return 'query ' + ref + ' answer malformed';
    if (vals[ti].length !== vals[vi].length || vals[ti].length > MAX_POINTS) return 'query ' + ref + ' answer malformed or too large';
    const lb = fields[vi].labels;
    const labels = (lb && typeof lb === 'object' && !Array.isArray(lb)) ? lb : {};
    const points = [];
    for (let i = 0; i < vals[ti].length; i++) {
      const t = vals[ti][i];
      if (typeof t !== 'number' || !isFinite(t)) return 'query ' + ref + ' answer malformed';
      points.push({ t, v: vals[vi][i] });
    }
    out.push({ labels, points });
  }
  return out;
}
const lastPoint = (s) => s.points.length ? s.points.reduce((a, b) => (b.t >= a.t ? b : a)) : null;
const truthy = (v) => v === true || v === 1 || v === '1' || v === 'true';
const positive = (v) => typeof v === 'number' && v > 0;

const cur = readRef('A');
if (typeof cur === 'string') return failed(cur);
const ever = readRef('B');
if (typeof ever === 'string') return failed(ever);
if (cur.length === 0) return done('not-deployed', 'no UniFi upgradeable series in the last 7 days (unpoller not writing or not deployed)');
const now = Date.now();
const state = new Map();
for (const s of cur) {
  const lp = lastPoint(s);
  if (!lp || now - lp.t > FRESH_MS || lp.t > now + 300000) continue;  // stale or future point: device not current
  const name = str(s.labels.name);
  state.set(name, (state.get(name) || false) || truthy(lp.v));
}
