const everTrue = new Set();
for (const s of ever) { const lp = lastPoint(s); if (lp && positive(lp.v)) everTrue.add(str(s.labels.name)); }
const pending = [];
const applied = [];
for (const [name, up] of state) {
  if (up) pending.push({ name, version: 'upgrade available' });
  else if (everTrue.has(name)) applied.push({ name, from: 'upgrade pending', to: 'up to date' });
